# Writes src/scenes.json for "How to Make Your Dream a Reality" (script.md), about 15 minutes. One narration clip per sentence.
# Per sentence: th = picture themes (src/images.json), big = the key word shown huge under the caption line
# (reel Dd0NzeWxryg), red = that word in red, gap = silence after.
import json
S = []
def s(text, th, big=None, red=False, gap=0.75):
    S.append(dict(id=f"s{len([x for x in S if 'text' in x]) + 1:03d}", text=text, th=th if isinstance(th, list) else [th], big=big, red=red, gap=gap))
def ch(num, title, dur=4.4): S.append(dict(id=f"ch{sum(1 for x in S if 'card' in x) + 1}", card="chapter", num=num, title=title, len=dur))

# ---- opening
s("If you have built castles in the air, your work need not be lost.", ["castle"], big="castles")
s("That is where they should be.", ["castle"], gap=0.3)
s("Now put the foundations under them.", ["build"], big="foundations", red=True, gap=0.8)
s("Henry David Thoreau wrote that in a cabin he built with his own hands, beside a pond in Massachusetts.", ["thoreau"], big="Thoreau")
s("He was not against dreaming.", ["thoreau", "dream"])
s("He spent two years alone in the woods, chasing a dream most people thought was foolish.", ["thoreau", "night"], big="foolish")
s("But he understood something most dreamers never do.", ["face"])
s("A dream is only the roof. Nobody lives in a roof.", ["castle"], big="roof", red=True, gap=0.7)
s("A few years before Thoreau went into the woods, the painter Thomas Cole made a series of four paintings called The Voyage of Life.", ["castle"], big="Voyage")
s("In the second one, a young man stands in a boat on a river, one arm stretched toward a shining palace floating in the clouds.", ["castle"], big="palace")
s("He does not look at the water. He does not see that the river is bending away from the palace, toward rapids and rocks.", ["storm", "castle"], big="rapids")
s("He sees only the castle.", ["castle"], gap=0.7)
s("Most of us are that young man. We have a castle in the air.", ["dream", "face"])
s("The book we will write. The body we will build. The business we will start. The life we will live once things finally calm down.", ["dream", "face", "night"])
s("We visit it every night. We furnish it in detail.", ["night", "castle"], big="night")
s("And every morning, we wake up in exactly the same place.", ["morning"], big="same", red=True, gap=0.7)
s("So this video is about one question.", ["face"], gap=0.3)
s("How does a dream leave your head and enter the world?", ["morning", "castle"], big="world", gap=1.0)

# ---- I
ch("I", "The castle and the ground")
s("Start with the strangest race of the twentieth century.", ["wright"], big="race")
s("For hundreds of years, people had dreamed of flying. Poets wrote about it. Inventors jumped from towers wearing wings and broke their legs.", ["lilienthal", "castle"], big="flying")
s("By 1903, two teams in America were close enough to believe they could build the first machine that would carry a man through the air under its own power.", ["lilienthal", "wright"], big="1903")
s("The first was led by Samuel Langley, the head of the Smithsonian Institution, one of the most respected scientists in America.", ["langley"], big="Langley")
s("He had fifty thousand dollars from the War Department, a staff of engineers, and the attention of the entire press.", ["langley", "crowd"], big="fifty")
s("He had already flown large steam-powered models without a pilot. Everyone expected him to finish the job.", ["langley"])
s("The second team was two brothers from Ohio who repaired bicycles for a living.", ["wright"], big="bicycles")
s("No degrees. No funding. Wilbur and Orville Wright paid for everything out of their own shop.", ["wright", "work"], big="Wright")
s("No newspaper was watching them. Almost nobody outside their family knew what they were doing.", ["wright", "night"])
s("On paper, it was not a race at all.", ["langley"], gap=0.9)

# ---- II
ch("II", "The grand moment")
s("Langley's machine was called the Aerodrome. It was launched from a catapult on top of a houseboat in the Potomac River.", ["langley"], big="Aerodrome")
s("Reporters waited in boats for days to watch it fly.", ["langley", "crowd"])
s("On the seventh of October 1903, the catapult fired, and the Aerodrome dropped straight into the water, as one reporter put it, like a handful of mortar.", ["langley", "storm"], big="water")
s("In December, they tried again. This time it broke apart in the air and fell into the river a second time. The pilot was pulled out of the freezing water.", ["langley", "storm"], big="again")
s("A newspaper wrote that a true flying machine might take one million to ten million years.", ["crowd"], big="million")
s("Langley was mocked in the press and in Congress. The money was withdrawn. He never tried again, and he died less than three years later.", ["langley", "night"], big="never")
s("He was not a fool. He was brilliant, and he worked hard.", ["langley", "face"])
s("But he had made the first mistake a dreamer can make. He went straight for the grand moment.", ["langley", "castle"], big="grand")
s("He tested the whole vision at once, in public, and when it failed, there was nothing to learn from but wreckage.", ["storm"], big="wreckage", red=True, gap=0.7)
s("This is the man who decides to change everything on Monday. A new diet, a new schedule, a new life, all at once.", ["face", "morning"], big="Monday")
s("And when Thursday comes and the whole thing collapses, he concludes that the dream was impossible, instead of seeing that the launch was wrong.", ["storm", "face"], big="impossible", gap=0.9)

# ---- III
ch("III", "The quiet trap")
s("The second trap is quieter. It belongs to the man who never launches at all.", ["face", "night"], big="never")
s("He reads, plans and prepares, waiting for the perfect moment and the perfect conditions.", ["night", "face"], big="perfect")
s("He knows everything about the dream except what it feels like to begin.", ["dream", "night"], gap=0.6)
s("And often, without noticing, he spends the energy of the dream on talking about it.", ["crowd", "face"], big="talking")
s("In 2009, the psychologist Peter Gollwitzer and his colleagues ran a series of experiments with students who wanted to become something, a lawyer, a psychologist.", ["scholar", "crowd"], big="2009")
s("Some of the students were asked to tell another person about their plans. Others kept them to themselves.", ["crowd"])
s("The ones who announced their intentions then worked on them less.", ["face"], big="less", red=True)
s("Being seen as the person with the dream had already given them some of the feeling of having it.", ["dream", "crowd"], big="feeling")
s("The mind had been paid in advance.", ["night"], gap=0.7)
s("Marcus Aurelius, the emperor of Rome, wrote a line in his private notebook that could have been written for this man.", ["stoic"], big="Marcus")
s("Waste no more time arguing about what a good man should be. Be one.", ["stoic"], big="Be one", red=True, gap=0.7)
s("The first man leaps too soon. The second never leaps.", ["face", "storm"], big="leaps")
s("They seem like opposites, but they have made the same mistake.", ["face"])
s("Both have mistaken the picture in their head for the work in the world.", ["dream", "work"], big="work", gap=1.0)

# ---- IV
ch("IV", "Foundations")
s("The Wrights did something different. They started with the problem that had killed the men before them.", ["wright"], big="different")
s("In 1896, the great German glider pioneer Otto Lilienthal, who had made around two thousand flights, fell from the sky and died.", ["lilienthal"], big="Lilienthal")
s("The brothers studied his death and decided that lift was not the real problem. Control was.", ["lilienthal", "wright"], big="Control", red=True)
s("A machine that could not be steered and balanced in a gust of wind would kill whoever flew it.", ["storm", "lilienthal"])
s("So before they ever built an engine, they built gliders, and flew them, again and again, for three summers.", ["wright", "dunes"], big="gliders")
s("They wrote to the Weather Bureau to find the windiest, emptiest beach in America. It was Kitty Hawk, on the coast of North Carolina.", ["dunes", "wright"], big="Kitty Hawk")
s("They lived there in a wooden shed, fighting sand, storms and clouds of mosquitoes.", ["dunes", "work"], big="mosquitoes")
s("The summer of 1901 went badly. Their glider produced far less lift than the published tables promised.", ["wright", "dunes"])
s("On the train home, Wilbur told his brother that man would not fly for fifty years.", ["wright", "night"], big="fifty years")
s("This is the moment where most dreams end. Not in a crash, but in a quiet sentence on the way home.", ["night", "face"], big="quiet", red=True, gap=0.7)
s("But instead of quitting, they did not trust the tables any more. They decided to find out for themselves.", ["wright", "work"])
s("They built a small wind tunnel in their shop out of a wooden box and a fan, and they tested around two hundred different wing shapes, one at a time.", ["wright", "work"], big="two hundred")
s("It was slow, unglamorous work. Nobody applauded. Nobody wrote about it.", ["work", "night"], big="slow")
s("The next summer, their new glider worked. They made somewhere between seven hundred and a thousand glides in a few weeks, learning to control the machine in the air.", ["wright", "dunes"], big="thousand")
s("Only then did they turn to the engine. Nobody would sell them one light enough, so their mechanic Charlie Taylor built it in six weeks.", ["work"], big="six weeks")
s("On the fourteenth of December 1903, Wilbur made the first attempt. The machine stalled and dug into the sand. He did not give up, and he did not call the press.", ["wright", "dunes"], big="stalled")
s("They repaired it and waited for the wind.", ["dunes", "morning"], gap=0.6)
s("On the 17th of December 1903, just nine days after Langley's second crash, Orville Wright lay on the lower wing and flew.", ["wright"], big="flew", red=True)
s("Twelve seconds. One hundred and twenty feet.", ["wright"], big="Twelve")
s("They flew four times that morning. On the last flight, Wilbur stayed in the air for fifty-nine seconds and covered more than eight hundred feet.", ["wright", "dunes"], big="fifty-nine")
s("The whole project had cost them about a thousand dollars.", ["wright", "work"], big="thousand")
s("Hardly anyone believed them at first. It took years before the world understood what had happened at Kitty Hawk.", ["crowd", "wright"])
s("In 1908, Wilbur sailed to France and flew in front of a crowd near Le Mans, banking and circling over the field.", ["crowd", "wright"], big="France")
s("The French aviators who had doubted him were stunned. One of them said simply, we are beaten.", ["crowd", "face"], big="beaten", red=True)
s("They did not have the bigger dream. They had the better foundations.", ["build", "wright"], big="foundations", red=True, gap=1.0)

# ---- V
ch("V", "The method")
s("So what are the foundations under a castle in the air? Look at what the Wrights actually did, and five steps appear.", ["castle", "wright"], gap=0.6)
s("First, name the dream precisely.", ["port"], big="precisely")
s("Seneca wrote that if a man does not know to which port he is sailing, no wind is favourable.", ["port", "stoic"], big="port")
s("The Wrights did not want to do something with flight. They wanted a machine that would carry a man, under its own power, and be controlled in the air.", ["wright"])
s("Not \"be successful\", but the exact thing, the exact number, the exact date.", ["work"], big="exact", red=True)
s("A vague dream cannot fail, and that is exactly why it can never succeed.", ["dream", "night"], gap=0.7)
s("Second, find the thing that will kill it.", ["storm"], big="kill")
s("For the Wrights, it was control. For you, it is probably not something in the world. It is something in you.", ["face", "storm"], big="you", red=True)
s("Your impatience. Your fear of looking foolish. The habit of stopping when it gets boring.", ["face"], big="impatience")
s("Name it as honestly as the Wrights named the death of Lilienthal.", ["lilienthal", "face"], gap=0.7)
s("Third, decide in advance what you will do when that obstacle appears.", ["night", "work"], big="advance")
s("Put it in a simple form. If this happens, then I will do that.", ["work"])
s("If I come home tired, then I will still write one page. If I miss a day, then I will never miss two.", ["night", "work"], big="never miss two")
s("Across nearly a hundred studies, people who made plans in exactly that form were far more likely to reach their goals than people who only intended to.", ["crowd", "work"], big="hundred")
s("The decision is made once, in a calm moment, so that it does not have to be made again in a weak one.", ["morning", "face"], gap=0.7)
s("Fourth, build the glider before the aeroplane.", ["wright", "lilienthal"], big="glider")
s("Make the smallest version of your dream that can be tested this week. A single chapter. A single customer. A single month of training.", ["work", "build"], big="smallest")
s("Every small failure is a wind tunnel. Every big failure is the Potomac.", ["wright", "storm"], big="Potomac", red=True, gap=0.7)
s("And fifth, show up every day, and look honestly at what you did.", ["morning", "night"], big="every day")
s("The novelist Anthony Trollope worked full time for the Post Office. So he wrote before work, starting at half past five in the morning.", ["writer"], big="Trollope")
s("He kept his watch on the desk and wrote two hundred and fifty words every quarter of an hour, for three hours, every day.", ["writer"], big="every quarter")
s("By the end of his life, he had written forty-seven novels.", ["writer", "build"], big="forty-seven", red=True)
s("Benjamin Franklin began each morning with a question. What good shall I do this day?", ["franklin", "morning"], big="morning")
s("And he ended each evening with another. What good have I done today?", ["franklin", "night"], big="today")
s("That evening question is where the dream meets the truth.", ["night"], gap=1.0)


# ---- VI
ch("VI", "The first stone")
s("There is one more detail in this story, and it may be the most important of all.", ["wright", "night"], gap=0.6)
s("In May 1899, before they had built anything, Wilbur Wright sat down and wrote a letter to the Smithsonian Institution.", ["wright", "writer"], big="1899")
s("The same institution run by Samuel Langley.", ["langley"], big="Langley", red=True)
s("He asked them for anything they had published on the subject of flight, and he described himself in one honest sentence.", ["writer", "wright"])
s("I am an enthusiast, but not a crank.", ["wright"], big="enthusiast")
s("The Smithsonian mailed him a small packet of pamphlets. Some of them were written by Langley himself.", ["langley", "writer"], big="pamphlets")
s("That packet was the first stone. Four and a half years later, the brothers flew, and the man whose papers they had read was still pulling his machine out of the river.", ["wright", "storm"], big="first stone", red=True, gap=0.8)
s("The first stone of a dream is almost always small, and almost always boring.", ["build", "work"], big="boring")
s("A letter. A phone call. A page. A walk around the block. A single honest look at your bank account.", ["writer", "morning"])
s("Nobody will applaud it, and that is exactly why so few people ever lay it.", ["night", "face"], gap=0.7)
s("Thoreau knew this too. When he built his cabin by the pond, he wrote down the cost of every board, every brick and every nail.", ["thoreau", "build"], big="every nail")
s("The whole house cost him twenty-eight dollars and twelve and a half cents.", ["thoreau"], big="twenty-eight")
s("The man who wrote about castles in the air was also the man who counted the nails.", ["thoreau", "castle"], big="nails", red=True, gap=0.7)
s("At the end of Walden, he wrote down what his two years in the woods had taught him.", ["thoreau", "night"])
s("If one advances confidently in the direction of his dreams, and endeavours to live the life which he has imagined, he will meet with a success unexpected in common hours.", ["thoreau", "morning"], big="advances", gap=0.8)
s("Look at the verbs in that sentence. Advances. Endeavours. Lives.", ["thoreau"], big="advances", red=True)
s("The dream gives the direction. Only the walking covers the distance.", ["morning", "build"], big="walking", gap=1.0)

# ---- close
s("Langley had the money, the fame and the vision. The brothers from Ohio had a method.", ["langley", "wright"], big="method", red=True)
s("Thomas Cole's young man is still reaching for the palace in the clouds, and his boat is still drifting toward the rocks.", ["castle", "storm"])
s("And that is the difference between a castle in the air and a house you can live in.", ["castle", "build"], big="house")
s("Keep your dream. It is where you are meant to live.", ["castle", "morning"])
s("But tonight, before you sleep, put one stone underneath it.", ["night", "build"], big="one stone", red=True)
s("And tomorrow, put another.", ["morning", "build"], gap=0.7)
s("The world will never answer what you imagine. It only answers what you build.", ["morning", "build"], big="build", red=True, gap=2.0)
json.dump(dict(voice="bm_george", speed=0.97, scenes=S), open("src/scenes.json", "w"), indent=1)
print(len([x for x in S if "text" in x]), "sentences,", sum(len(x["text"].split()) for x in S if "text" in x), "words")
